CREATE TABLE business_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), signal_type text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, severity text NOT NULL CHECK(severity IN ('INFO','LOW','MEDIUM','HIGH','CRITICAL')), title text NOT NULL, description text NOT NULL, metric_name text NOT NULL DEFAULT '', metric_value numeric(18,3), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','RESOLVED','EXPIRED')), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, UNIQUE(organization_id,signal_type,entity_type,entity_id), UNIQUE(organization_id,id)); CREATE INDEX business_signals_org_status_idx ON business_signals(organization_id,status,severity);
